package com.project.loyalty.service;
import com.project.loyalty.dto.*; import com.project.loyalty.exception.ApiException; import com.project.loyalty.model.*; import com.project.loyalty.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class LoyaltyService {
 private final CustomerRepository customers; private final PointTransactionRepository txs;
 public LoyaltyService(CustomerRepository c,PointTransactionRepository t){customers=c;txs=t;}
 public List<Customer> all(){return customers.findAll();} public Customer get(Long id){return customers.findById(id).orElseThrow(()->new ApiException("Customer not found"));}
 public Customer create(Customer c){ if(customers.findByEmail(c.getEmail()).isPresent()) throw new ApiException("Email already registered"); c.setId(null);c.setPointsBalance(0);c.setLifetimePoints(0);c.setTier(Tier.BRONZE);return customers.save(c); }
 public Customer update(Long id,Customer in){Customer c=get(id); if(!c.getEmail().equalsIgnoreCase(in.getEmail()) && customers.findByEmail(in.getEmail()).isPresent())throw new ApiException("Email already registered"); c.setName(in.getName());c.setEmail(in.getEmail());c.setPhone(in.getPhone());return customers.save(c);}
 public void delete(Long id){Customer c=get(id); if(!txs.findByCustomerIdOrderByCreatedAtDesc(id).isEmpty()) throw new ApiException("Cannot delete customer with transaction history"); customers.delete(c);}
 @Transactional public Map<String,Object> earn(Long id,EarnRequest r){Customer c=get(id); Tier before=c.getTier(); int earned=(int)Math.floor(r.getPurchaseAmount()*before.getMultiplier()); if(earned<1)earned=1; c.setPointsBalance(c.getPointsBalance()+earned);c.setLifetimePoints(c.getLifetimePoints()+earned);c.setTier(Tier.fromLifetimePoints(c.getLifetimePoints()));customers.save(c); saveTx(c,TransactionType.EARN,earned,r.getPurchaseAmount(),r.getNote()); return result(c,earned,before);}
 @Transactional public Map<String,Object> redeem(Long id,PointsRequest r){Customer c=get(id); if(r.getPoints()>c.getPointsBalance())throw new ApiException("Insufficient points. Available: "+c.getPointsBalance()); c.setPointsBalance(c.getPointsBalance()-r.getPoints());customers.save(c);saveTx(c,TransactionType.REDEEM,-r.getPoints(),0,r.getNote());return result(c,-r.getPoints(),c.getTier());}
 @Transactional public Map<String,Object> adjust(Long id,AdjustmentRequest r){Customer c=get(id); int p=r.getPoints(); if(p==0)throw new ApiException("Adjustment cannot be zero"); if(c.getPointsBalance()+p<0)throw new ApiException("Adjustment would make balance negative"); c.setPointsBalance(c.getPointsBalance()+p); if(p>0){c.setLifetimePoints(c.getLifetimePoints()+p);c.setTier(Tier.fromLifetimePoints(c.getLifetimePoints()));} customers.save(c);saveTx(c,TransactionType.ADJUSTMENT,p,0,r.getNote());return result(c,p,c.getTier());}
 public List<PointTransaction> history(Long id){get(id);return txs.findByCustomerIdOrderByCreatedAtDesc(id);}
 public Map<String,Object> tiers(){Map<String,Object> m=new LinkedHashMap<>();for(Tier t:Tier.values())m.put(t.name(),Map.of("threshold",t.getThreshold(),"pointsPerRupee",t.getMultiplier(),"discountPercent",t.getDiscountPercent()));return m;}
 private void saveTx(Customer c,TransactionType type,int p,double amt,String note){PointTransaction t=new PointTransaction();t.setCustomer(c);t.setType(type);t.setPoints(p);t.setPurchaseAmount(amt);t.setNote(note);txs.save(t);}
 private Map<String,Object> result(Customer c,int changed,Tier before){Map<String,Object> m=new LinkedHashMap<>();m.put("customer",c);m.put("pointsChanged",changed);m.put("tierUpgraded",before!=c.getTier());m.put("discountPercent",c.getTier().getDiscountPercent());return m;}
}
